code='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    split = None
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            split = ("h", r, row[0])
            break
    if split is None:
        for c in range(w):
            vals = [grid[r][c] for r in range(h)]
            if len(set(vals)) == 1:
                split = ("v", c, vals[0])
                break
    if split is None:
        raise ValueError("no uniform separator")
    axis, k, _ = split
    if axis == "h":
        a, b = grid[:k], grid[k+1:]
    else:
        a = [row[:k] for row in grid]
        b = [row[k+1:] for row in grid]
    ca, cb = Counter(x for row in a for x in row), Counter(x for row in b for x in row)
    # The panel with the more dominant background is the sparse marker panel.
    sparse, noisy = (a, b) if max(ca.values()) / sum(ca.values()) > max(cb.values()) / sum(cb.values()) else (b, a)
    counts = Counter(x for row in sparse for x in row)
    marker = min(counts, key=counts.get)
    out = [[marker for _ in row] for row in noisy]
    for r in range(len(noisy)):
        for c in range(len(noisy[0])):
            if sparse[r][c] == marker and noisy[r][c] == marker:
                out[r][c] = 3
    return out
'''
